package com.astrocare.service;
import com.astrocare.entity.*; import com.astrocare.exception.*; import com.astrocare.repository.*; import com.lowagie.text.Document; import com.lowagie.text.FontFactory; import com.lowagie.text.Paragraph; import com.lowagie.text.Phrase; import com.lowagie.text.PageSize; import com.lowagie.text.Table; import com.lowagie.text.Cell; import com.lowagie.text.pdf.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import java.io.*; import java.time.*; import java.util.*;
@Service @RequiredArgsConstructor public class ReportService {private final AstronautRepository astronauts;private final VitalSignRepository vitals; public byte[] pdf(Long id)throws IOException{Astronaut a=astronauts.findById(id).orElseThrow(()->new ResourceNotFoundException("Astronaut not found"));Document d=new Document(PageSize.A4);ByteArrayOutputStream out=new ByteArrayOutputStream();PdfWriter.getInstance(d,out);d.open();d.addTitle("AstroCare Clinical Report");d.add(new Paragraph("AstroCare Clinical Report",FontFactory.getFont(FontFactory.HELVETICA_BOLD,18)));d.add(new Paragraph("Generated: "+LocalDateTime.now(ZoneOffset.UTC)));d.add(new Paragraph("Astronaut: "+a.getFullName()+" ("+a.getCallSign()+")"));d.add(new Paragraph("Status: "+a.getStatus()));d.add(new Paragraph("Baseline HR: "+a.getBaselineHeartRateBpm()+" bpm | SpO2: "+a.getBaselineSpo2Pct()+"%"));List<VitalSign> rows=vitals.findByAstronautIdAndRecordedAtBetweenOrderByRecordedAtAsc(id,LocalDateTime.now(ZoneOffset.UTC).minusHours(24),LocalDateTime.now(ZoneOffset.UTC));Table t=new Table(5);for(String h:List.of("Recorded at","HR","SpO2","BP","Temp"))t.addCell(new Cell(new Phrase(h)));for(VitalSign v:rows){t.addCell(v.getRecordedAt().toString());t.addCell(v.getHeartRateBpm().toString());t.addCell(v.getSpo2Pct().toString());t.addCell(v.getSystolicMmHg()+"/"+v.getDiastolicMmHg());t.addCell(v.getCoreTempC().toString());}d.add(t);d.close();return out.toByteArray();}}
